    ["Insert"] = "Insert",
    ["Key bindings"] = "Controles",
    ["Key bindings need Codeware, and this game does not have it. Open Help for what is missing."] = "Los controles necesitan Codeware, y este juego no lo tiene. Abre Ayuda para ver qué falta.",
    ["Key or button"] = "Tecla o botón",
    ["Left arrow"] = "Flecha izq.",
    ["Menu"] = "Menú",
    ["No key was pressed, so nothing changed."] = "No se pulsó ninguna tecla, así que no cambió nada.",
    ["Not available"] = "No disponible",
    ["Not set"] = "Sin asignar",
    ["Num lock"] = "Bloq Num",
    ["Page down"] = "AvPág",
    ["Page up"] = "RePág",
    ["Pause"] = "Pausa",
    ["Press it, then the key or controller button you want. Esc or B cancels. It works at once."] = "Púlsalo y luego la tecla o el botón del mando que quieras. Esc o B cancela. Funciona al momento.",
    ["Press it to open the Companion Manager while you play."] = "Púlsala para abrir el Gestor de compañeros mientras juegas.",
    ["Press it to type to the character you face. Facing nobody, you type to the first member of your party."] = "Púlsala para escribir al personaje que tienes delante. Si no miras a nadie, escribes al primer miembro de tu grupo.",
    ["Press it to type to Johnny, the voice in your head, wherever you face. It needs Johnny in your head turned on in Settings."] = "Púlsala para escribir a Johnny, la voz de tu cabeza, hacia donde mires. Necesita que Johnny en tu cabeza esté activado en Ajustes.",
    ["Press it to type to the characters around you at once. Facing nobody, you type to the first member of your party and two others from it."] = "Púlsala para escribir a los personajes que tienes alrededor a la vez. Si no miras a nadie, escribes al primer miembro de tu grupo y a otros dos del grupo.",
    ["Press the key or controller button for {action}. Esc or B cancels."] = "Pulsa la tecla o el botón del mando para {action}. Esc o B cancela.",
    ["Print screen"] = "Impr Pant",
    ["Remove the key or button you set here."] = "Quita la tecla o el botón que asignaste aquí.",
    ["Right arrow"] = "Flecha der.",
    ["Scroll lock"] = "Bloq Despl",
    ["Space"] = "Espacio",
    ["Tab"] = "Tab",
    ["Talk by text"] = "Hablar por texto",
    ["Talk by voice"] = "Hablar por voz",
    ["Talk to Johnny by text"] = "Hablar con Johnny por texto",
    ["Talk to Johnny by voice"] = "Hablar con Johnny por voz",
    ["That key is already used for another action."] = "Esa tecla ya está usada para otra acción.",
    ["The mod’s key bindings could not be loaded. Open Help for what is wrong."] = "No se pudieron cargar los controles del mod. Abre Ayuda para ver qué falla.",
    ["The mod’s scripts did not load, so no key can be set. Open Help for what is wrong."] = "Los scripts del mod no se cargaron, así que no se puede asignar ninguna tecla. Abre Ayuda para ver qué falla.",
    ["Up arrow"] = "Flecha arriba",
    ["View"] = "Vista",
    ["{action} cleared."] = "{action}: borrado.",
    ["{action} is set to {key}."] = "{action} está asignado a {key}.",
    ["{key} is already used for {other}. Choose another."] = "{key} ya se usa para {other}. Elige otra.",
    ["10 minutes"] = "10 minutos",
    ["2 minutes"] = "2 minutos",
    ["5 minutes"] = "5 minutos",
    ["Cancel this meeting. She is not told."] = "Cancelar la cita. Ella no se entera.",
    ["Car"] = "Coche",
    ["Choose how long she waits."] = "Elige cuánto tiempo espera.",
    ["Choose how she arrives."] = "Elige cómo llega.",
    ["Choose one of the listed options."] = "Elige una de las opciones de la lista.",
    ["Choose when she arrives."] = "Elige cuándo llega.",
    ["Companions travel to you when you invite them: they walk or drive in, text you, wait, and remember if you never come.\n\nOff by default."] = "Los compañeros viajan hasta ti cuando los invitas: llegan andando o en coche, te escriben, esperan y recuerdan si nunca vienes.\n\nDesactivado por defecto.",
    ["Fine. Call me when you know what you want."] = "Vale. Llámame cuando sepas lo que quieres.",
    ["How long she waits"] = "Cuánto tiempo espera",
    ["How long she waits for you after arriving right now. After a timed arrival she waits as long as the delay you chose. The wait stops while you are in a fight, a scene or a menu."] = "Cuánto tiempo espera por ti al llegar en este momento. Tras una llegada programada espera tanto como el retraso que elegiste. La espera se detiene mientras estés en un combate, una escena o un menú.",
    ["How she arrives"] = "Cómo llega",
    ["I waited {minutes} minutes at {place} and you never showed. Forget it."] = "Llevo {minutes} minutos esperando en {place} y no apareciste. Olvídalo.",
    ["I'm here at {place}. Where are you?"] = "Estoy aquí, en {place}. ¿Dónde estás?",
    ["Immersive invitations"] = "Invitaciones inmersivas",
    ["In 10 minutes"] = "En 10 minutos",
    ["In 2 minutes"] = "En 2 minutos",
    ["In 5 minutes"] = "En 5 minutos",
    ["Invite a companion and she really travels to you: she appears out of sight, walks or drives in, texts you when she is there and waits for you."] = "Invita a un compañero y de verdad viajará hasta ti: aparece fuera de tu vista, llega andando o en coche, te escribe cuando está allí y te espera.",
    ["Meet at my waypoint when I ask"] = "Quedar en mi punto de ruta si lo pido",
    ["Off: Invite brings a companion to your side at once.\n\nOn: a companion you invite, by the Invite button, the Contacts tab or a text, travels to you and arrives after the time you choose here. She texts you when she is there, waits, and leaves angry (and remembers it) if you never come."] = "Desactivado: Invitar trae a un compañero a tu lado al instante.\n\nActivado: un compañero que invites, con el botón Invitar, la pestaña de Contactos o un mensaje, viaja hasta ti y llega tras el tiempo que elijas aquí. Te escribe cuando está allí, espera y se marcha enfadado (y lo recuerda) si nunca vienes.",
    ["Right now"] = "Ahora",
    ["Right now: she is on her way as soon as she is ready.\n\nIn 2, 5 or 10 minutes: real minutes of play, so she arrives at that time. She then waits as long as that delay."] = "Ahora: va hacia ti en cuanto esté lista.\n\nEn 2, 5 o 10 minutos: minutos reales de juego, así que llega a esa hora. Luego espera tanto como ese retraso.",
    ["She texts you"] = "Te escribe",
    ["She texts you when she arrives, when you cancel and when she gives up. Off: no texts (she still remembers being stood up)."] = "Te escribe cuando llega, cuando cancelas y cuando se rinde. Desactivado: sin mensajes (aun así recuerda que la dejaste plantada).",
    ["Something came up and I can't make it. Sorry."] = "Me ha surgido algo y no puedo ir. Lo siento.",
    ["Walk"] = "A pie",
    ["Walk: she appears out of your sight and walks to you.\n\nCar: when a road is near she drives in, stops on the road, gets out and walks the rest. Without a road she walks. The car stays near for a ride, and is removed when she leaves your group or you both go far from it."] = "A pie: aparece fuera de tu vista y camina hasta ti.\n\nCoche: si hay una carretera cerca, llega conduciendo, para en la carretera, baja y recorre el resto a pie. Sin carretera, camina. El coche se queda cerca para el viaje y desaparece cuando ella deja tu grupo o si os alejáis mucho del coche.",
    ["When she arrives"] = "Cuando llega",
    ["When you ask her to come to your waypoint and a map pin is set, she goes there and says so. Off: she always comes to where you are."] = "Cuando le pides que venga a tu punto de ruta y hay un marcador en el mapa, va allí y lo dice. Desactivado: siempre viene a donde estás.",
    ["Your position cannot be read yet."] = "Todavía no se puede leer tu posición.",
    ["on her way"] = "de camino",
    ["the meeting spot"] = "el punto de encuentro",
    ["waiting at {place}"] = "esperando en {place}",
    ["{name} is already on the way."] = "{name} ya está de camino.",
    ["{name} is on her way."] = "{name} está de camino.",
    ["{name} is on her way. About {minutes} minutes."] = "{name} está de camino. Unos {minutes} minutos.",
    ["{name} · {state}"] = "{name} · {state}",
    ["{name}: Good to see you. Let us go."] = "{name}: Qué bien verte. Vamos.",
    ["Corpo Plaza"] = "Corpo Plaza",
    ["Heywood Glen"] = "Heywood Glen",
    ["Megabuilding H10"] = "Megabuilding H10",
    ["Move out"] = "Que se mude",
    ["That companion is not available."] = "Ese compañero no está disponible.",
    ["Watson Northside"] = "Watson Northside",
    ["Westbrook Japantown"] = "Westbrook Japantown",
    ["You do not have that apartment."] = "No tienes ese apartamento.",
    ["at home"] = "en casa",
    ["out"] = "fuera",
    ["with you"] = "contigo",
    ["{count} more housemates"] = "{count} compañeros de piso más",
    ["{name} has moved out."] = "{name} ya no vive contigo.",
    ["{name} is back at home."] = "{name} ha vuelto a casa.",
    ["{name} joins you."] = "{name} se une a ti.",
    ["{name} moves into {apartment}."] = "{name} se muda a {apartment}.",
    ["{name} now lives in {apartment} and stays in your party until sent home."] = "{name} vive ahora en {apartment} y sigue en tu grupo hasta que se vaya a casa.",
    ["{name} stops living at your place. She stays as she is otherwise."] = "{name} deja de vivir contigo. Lo demás no cambia.",
    ["{name} · lives in {apartment} · {state}"] = "{name} · vive en {apartment} · {state}",
    ["Companions change outfits"] = "Compañeros cambian de ropa",
    ["Your party’s companions change outfits now and then: another look by day and by night, and casual clothes at home, where the character has them.\n\nOnly out of your sight, never in front of you, and only for your party’s own copies, never the game’s own characters. Turning this off keeps what they wear now."] = "Los compañeros de tu grupo cambian de atuendo de vez en cuando: otro look de día y otro de noche, y ropa informal en casa, cuando el personaje la tiene.\n\nSolo fuera de tu vista, nunca delante de ti, y solo en las copias propias de tu grupo, nunca en los personajes del juego. Si desactivas esto, siguen con la ropa que llevan en ese momento.",
    ["Choose how often companions speak up."] = "Elige con qué frecuencia hablan los compañeros.",
    ["Companions speak up"] = "Los compañeros hablan",
    ["How V is doing according to other mods, when they are installed: Dark Future’s tiredness, hunger, thirst, nerve and addictions, for example. Also what V visibly wears while an Equipment-EX outfit is on, so characters describe the outfit and not the clothes it hides.\n\nOff by default. Off: it is not sent, and nothing is read from those mods."] = "Cómo está V según otros mods, si están instalados: por ejemplo, cansancio, hambre, sed, nervios y adicciones de Dark Future. También lo que V lleva puesto a la vista mientras hay un conjunto de Equipment-EX activo, para que los personajes describan el conjunto y no la ropa que oculta.\n\nDesactivado por defecto. Desactivado: no se envía nada, y no se lee nada de esos mods.",
    ["How long it has been since V last talked to this character, in the game and in real days: since last night, or days ago. Said only when the gap is long enough to matter, and not again in the same conversation.\n\nOff: it is not sent, and the mod stops reading the game clock for it."] = "Cuánto tiempo ha pasado desde la última vez que V habló con este personaje, en el juego y en días reales: desde anoche, o desde hace días. Solo se dice cuando la distancia es lo bastante larga para importar, y no se repite en la misma conversación.\n\nDesactivado: no se envía nada, y el mod deja de leer el reloj del juego para esto.",
    ["Music and TV"] = "Música y TV",
    ["Other mods’ state"] = "Estado de otros mods",
    ["Speaks up normally"] = "Habla normalmente",
    ["The song playing on the car radio while V rides with the character, or on V’s pocket radio, and what is on a TV near V.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "La canción que suena en la radio del coche cuando V viaja con el personaje, o en la radio de bolsillo de V, y lo que hay en una TV cerca de V.\n\nDesactivado: no se envía nada, y el mod deja de leerlo del juego.",
    ["Time since last talk"] = "Tiempo desde la última conversación",
    ["Companions in your party sometimes start talking on their own, at a calm moment or after a scene. With two or more near you, it is often a short chat between up to three of them, and you can join in by talking. Never during fights, scenes, calls or menus.\n\nRarely: about 2 an hour. Normally: about 4. Often (the default): about 6.\n\nWith Johnny speaking up too, the rates add up and they take turns."] = "Los compañeros a veces hablan por su cuenta, en un momento tranquilo o tras una escena. Con dos o más cerca, suele ser una breve charla entre hasta tres, en la que puedes unirte hablando. Nunca durante peleas, escenas, llamadas o menús.\n\nPocas veces: unas 2 por hora de juego. Normalmente: unas 4. A menudo (por defecto): unas 6.\n\nCuando Johnny también habla, las dos frecuencias se suman y se turnan.",
    ["Johnny Silverhand answers the Talk to Johnny keys, as the voice in V’s head, once the story has him there. Give Talk to Johnny a key on the Key bindings page: none is set by default.\n\nOn: he answers when you talk to him. Rarely: he also speaks up on his own, about 2 an hour. Normally: about 4. Often: about 6.\n\nWith companions speaking up too, the rates add up and they take turns."] = "Johnny Silverhand responde a las teclas de Hablar con Johnny, como voz en la mente de V, cuando la trama lo sitúa allí. Asigne una tecla a Hablar con Johnny en la página Controles: por defecto no hay ninguna.\n\nActivado: responde cuando le habla. Pocas veces: también habla por su cuenta, unas 2 por hora. Normalmente: unas 4. A menudo: unas 6.\n\nCuando también hablan los compañeros, las frecuencias se suman y se turnan.",
    ["Choose which live game info the characters are told, such as location, time, weather, company, health, money, gear, quests, music and TV, and other mods’ state.\n\nAll on by default except other mods’ state, which is off. An off kind is not sent to any conversation provider."] = "Elige qué información del juego en vivo se les comunica a los personajes, como ubicación, hora, clima, compañeros presentes, salud, dinero, equipo, misiones, música y TV, y el estado de otros mods.\n\nTodo está activado por defecto, salvo el estado de otros mods, que está desactivado. Un tipo desactivado no se envía a ningún proveedor de conversación.",
    ["Housemates"] = "Compañeros de piso",
    ["Housemates talk to each other"] = "Los compañeros de piso hablan entre ellos",
    ["When two or more housemates are home with you, they talk to each other now and then."] = "Cuando dos o más compañeros de piso están en casa contigo, hablan entre ellos de vez en cuando.",
    ["Characters you tell they can stay at your place move into your apartments and live there."] = "Los personajes a los que dices que pueden quedarse en tu casa se mudan a tus apartamentos y viven allí.",
    ["Characters you tell they can stay at your place move into your apartments and live there.\n\nOff by default."] = "Los personajes a los que dices que pueden quedarse en tu casa se mudan a tus apartamentos y viven allí.\n\nDesactivado por defecto.",
    ["On: characters you tell they can stay at your place move into your apartments and live there, and you can call them along.\n\nOff: nothing of this runs. Turning it off removes them from your apartments but remembers who lived there, so turning it on brings them back."] = "Activado: los personajes a los que dices que pueden quedarse en tu casa se mudan a tus apartamentos y viven allí, y puedes llevártelos contigo.\n\nDesactivado: nada de esto funciona. Al desactivarlo se van de tus apartamentos, pero se recuerda quién vivía allí, así que al activarlo de nuevo vuelven.",
    ["OmniVoice Python"] = "OmniVoice Python",
    ["OmniVoice’s code could not load in it"] = "el código de OmniVoice no se pudo cargar en él",
    ["PyTorch is not installed in it"] = "PyTorch no está instalado en él",
    ["Your own Python (omni-python.txt) is being tested. Open this page again in a minute."] = "Tu propio Python (omni-python.txt) se está probando. Abre esta página de nuevo en un minuto.",
    ["Your own Python (omni-python.txt) is tested when OmniVoice starts or when this page checks again."] = "Tu propio Python (omni-python.txt) se prueba cuando OmniVoice se inicia o cuando esta página vuelve a verificar.",
    ["Your own Python (omni-python.txt) runs OmniVoice with {backend} on {card}. Experimental."] = "Tu propio Python (omni-python.txt) ejecuta OmniVoice con {backend} en {card}. Experimental.",
    ["Your own Python (omni-python.txt) was not used: {reason}. OmniVoice uses the Runtime’s Python, which needs an NVIDIA card."] = "Tu propio Python (omni-python.txt) no se utilizó: {reason}. OmniVoice utiliza el Python del Runtime, que requiere una tarjeta NVIDIA.",
    ["a test on the graphics card failed"] = "una prueba en la tarjeta gráfica falló",
    ["it did not start or did not answer in time"] = "no se inició o no respondió a tiempo",
    ["its PyTorch finds no graphics card (no CUDA or ROCm)"] = "su PyTorch no encuentra tarjeta gráfica (sin CUDA ni ROCm)",
    ["the OmniVoice pack is not installed"] = "el paquete OmniVoice no está instalado",
    ["the file does not name a python.exe that exists"] = "el archivo no especifica un python.exe que exista",
    ["the module {module} is missing in it"] = "el módulo {module} falta en él",
    ["1 minute"] = "1 minuto",
    ["2 people"] = "2 personas",
    ["3 people"] = "3 personas",
    ["4 people"] = "4 personas",
    ["Every character who lives at your place moves out at once, from every apartment. Party members who do not live there are not touched. A housemate who is with you stays in your party."] = "Todos los personajes que viven contigo se mudan a la vez, desde todos los apartamentos. Los miembros del grupo que no viven ahí no se ven afectados. Un compañero de piso que está contigo sigue en el grupo.",
    ["Evict"] = "Desalojar",
    ["Evict all housemates"] = "Desalojar a todos los compañeros de piso",
    ["Housemates in one chat"] = "Compañeros de piso en un chat",
    ["Housemates moved out: {count}"] = "Compañeros de piso se mudaron: {count}",
    ["How long the housemates stay quiet after a chat before they may start another. The Companions speak up setting still limits how many chats come in an hour."] = "Cuánto tiempo permanecen en silencio los compañeros de piso después de un chat antes de poder iniciar otro. La configuración de Los compañeros hablan sigue limitando cuántos chats llegan en una hora.",
    ["How many housemates join one chat when that many are home near each other. They speak one at a time. With fewer at home, the chat is as big as it can be."] = "Cuántos compañeros de piso se unen a un chat cuando ese número está en casa cerca el uno del otro. Hablan uno a la vez. Con menos en casa, el chat es lo más grande que puede ser.",
    ["Move-in apartment"] = "Apartamento de mudanza",
    ["Nobody lives at your place."] = "Nadie vive en tu casa.",
    ["Pause between chats"] = "Pausa entre chats",
    ["Where a character moves in when you say she can stay but name no apartment and you are not standing in one of yours.\n\nAsk me: she asks which one. Otherwise she takes the apartment you pick here. Only the apartments you own are listed."] = "Dónde se muda un personaje cuando dices que puede quedarse pero no nombras apartamento y no estás parado en uno del tuyo.\n\nPregúntame: ella pregunta cuál. Si no, toma el apartamento que eliges aquí. Solo se enumeran los apartamentos que posees.",
    ["Ask me"] = "Pregúntame",
    ["Could not start"] = "No se pudo iniciar",
    ["Did not start"] = "No se inició",
    ["If the folder is there, the newest log in red4ext/logs says why RED4ext did not load it: an antivirus that removed a file, or a missing Visual C++ runtime."] = "Si la carpeta está, el log más reciente en red4ext/logs indica por qué RED4ext no la cargó: un antivirus borró un archivo o falta el Visual C++ runtime.",
    ["Load a save first. A key can be set only while a game is loaded."] = "Carga primero una partida. Una tecla solo se puede asignar con una partida cargada.",
    ["No key press reached the mod, so nothing changed. If keys do not arrive from this menu, set the key in Cyber Engine Tweaks’ Bindings: it works the same."] = "El mod no recibió ninguna pulsación, así que no cambió nada. Si las teclas no llegan desde este menú, asigna la tecla en los controles de Cyber Engine Tweaks: funciona igual.",
    ["Runtime incomplete"] = "Runtime incompleto",
    ["Runtime not loaded"] = "Runtime no cargado",
    ["Service not running ({reason})"] = "Servicio no activo ({reason})",
    ["The Runtime’s plugin is loaded, but the conversation service left no trace in this session. launcher.log in red4ext/plugins/AiNpcCyberpunkCode says why: launcher.ini switched off, Node missing, or Node blocked by a security program. Fix that, then restart the game."] = "El plugin del Runtime está cargado, pero el servicio de conversación no dejó rastro en esta sesión. launcher.log en red4ext/plugins/AiNpcCyberpunkCode indica por qué: launcher.ini desactivado, Node no encontrado o Node bloqueado por un programa de seguridad. Corrígelo y luego reinicia el juego.",
    ["The conversation service cannot see this mod’s folder in the game: a mod manager’s virtual folders, or a folder it may not read. Extract the Runtime straight into the Cyberpunk 2077 folder, or start the game from the mod manager that holds the Runtime."] = "El servicio de conversación no puede ver la carpeta de este mod en el juego: carpetas virtuales de un gestor de mods, o una carpeta que no tiene permiso para leer. Extrae el Runtime directamente en la carpeta de Cyberpunk 2077, o inicia el juego desde el gestor de mods que contiene el Runtime.",
    ["The conversation service was started and never reported back. A security program probably stopped it at once, or Node cannot run on this PC. Allow red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe in your security program, then restart the game."] = "El servicio de conversación se inició pero nunca respondió. Probablemente un programa de seguridad lo detuvo al momento, o Node no puede ejecutarse en este PC. Permite red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe en tu programa de seguridad y luego reinicia el juego.",
    ["Windows would not let the game start the conversation service (error {error}). A security program may be blocking node.exe in red4ext/plugins/AiNpcCyberpunkMod/app/node: allow it, then restart the game."] = "Windows no permitió que el juego iniciara el servicio de conversación (error {error}). Un programa de seguridad podría estar bloqueando node.exe en red4ext/plugins/AiNpcCyberpunkMod/app/node: permítelo y luego reinicia el juego.",
    ["Add a server address first."] = "Añada primero una dirección de servidor.",
    ["Asks the server three times who it is and shows whether it is reachable, how long it takes to answer and its version. It sends no speech."] = "Pregunta tres veces al servidor quién es y muestra si es accesible, cuánto tarda en responder y su versión. No envía voz.",
    ["Connected. The server speaks with {voice}."] = "Conectado. El servidor habla con {voice}.",
    ["Custom voices"] = "Voces personalizadas",
    ["Deletes the saved server address. Remote OmniVoice needs one to speak."] = "Elimina la dirección de servidor guardada. OmniVoice remoto necesita una para hablar.",
    ["It answers in {ms} ms."] = "Responde en {ms} ms.",
    ["Its voice runs on {device}."] = "Su voz se ejecuta en {device}.",
    ["Loading"] = "Cargando",
    ["Not connected. Replies show as text until the server answers."] = "No conectado. Las respuestas se muestran como texto hasta que el servidor responda.",
    ["Nothing answered at that address. Check that the server is running, that the address and port are right and that both PCs are on the same network. A server started with its default only listens on its own PC: start it with the listen address 0.0.0.0."] = "Ninguna respuesta en esa dirección. Compruebe que el servidor está en marcha, que la dirección y el puerto son correctos y que ambos PC están en la misma red. Un servidor iniciado con la configuración predeterminada solo escucha en su propio PC: inícielo con la dirección de escucha 0.0.0.0.",
    ["Off. OmniVoice runs on this PC."] = "Desactivado. OmniVoice se ejecuta en este PC.",
    ["On, but no server address is saved. OmniVoice cannot speak yet."] = "Activado, pero no hay ninguna dirección de servidor guardada. OmniVoice todavía no puede hablar.",
    ["On, but no server address is saved. Pocket is used until you add one."] = "Activado, pero no hay ninguna dirección de servidor guardada. Mientras no añada una, se usa Pocket.",
    ["On, but no server address is saved. The server is not used yet."] = "Activado, pero no hay ninguna dirección de servidor guardada. El servidor todavía no se usa.",
    ["On, but a cloud voice is chosen under Companion voices, so the server is not used."] = "Activado, pero en Voces de compañeros hay elegida una voz de la nube, así que no se usa el servidor.",
    ["On. Waiting for the conversation service."] = "Activado. Esperando al servicio de conversación.",
    ["Paste address"] = "Pegar dirección",
    ["Remote OmniVoice"] = "OmniVoice remoto",
    ["Render the voices on another PC or graphics card that runs the OmniVoice server, so this PC keeps its frames.\n\nTurn it on, press Apply and add the server address below. The server then speaks for every Pocket or OmniVoice choice under Companion voices; a cloud voice stays as chosen. If it cannot be reached, replies show as text and the mod retries every few seconds."] = "Procesa las voces en otro PC o tarjeta gráfica que ejecute el servidor de OmniVoice, así este PC mantiene sus fotogramas.\n\nActívelo, pulse Aplicar y añada abajo la dirección del servidor. Habla por cada opción de Pocket u OmniVoice en Voces de compañeros; una voz de la nube se mantiene. Sin conexión, las respuestas se muestran como texto y el mod reintenta cada pocos segundos.",
    ["Render the OmniVoice voices on another PC or graphics card that runs the OmniVoice server."] = "Procesa las voces de OmniVoice en otro PC o tarjeta gráfica que ejecute el servidor de OmniVoice.",
    ["Render Pocket and OmniVoice voices on another PC or graphics card: the on/off switch, the server address and a connection test. It works whichever of those voices is chosen above."] = "Procesa las voces de Pocket y OmniVoice en otro PC o tarjeta gráfica: el interruptor de encendido y apagado, la dirección del servidor y una prueba de conexión. Funciona con cualquiera de esas voces que se elija arriba.",
    ["Server address"] = "Dirección del servidor",
    ["Something answered, but it is not the OmniVoice server. Check the port."] = "Algo respondió, pero no es el servidor de OmniVoice. Compruebe el puerto.",
    ["Start the OmniVoice server on the other PC. Its window shows the address to use, for example 192.168.1.20:8765. Copy it, then choose Paste address. It is read from the clipboard once and saved on this computer.\n\nOn the same PC use 127.0.0.1:8765. You can also write address=192.168.1.20:8765 in player-remote-omnivoice.txt in the conversation service folder.\n\nNothing is sent to it until Remote OmniVoice is on and OmniVoice is chosen, or you press Test."] = "Inicie el servidor de OmniVoice en el otro PC. Su ventana muestra la dirección que hay que usar, por ejemplo 192.168.1.20:8765. Cópiela y luego elija Pegar dirección. Se lee del portapapeles una vez y se guarda en este equipo.\n\nEn el mismo PC use 127.0.0.1:8765. También puede escribir address=192.168.1.20:8765 en player-remote-omnivoice.txt en la carpeta del servicio de conversación.\n\nNo se envía nada hasta que OmniVoice remoto esté activado y se elija OmniVoice, o hasta que pulse Probar.",
    ["Status"] = "Estado",
    ["The OmniVoice server cannot be reached. Replies show as text until it answers. The mod asks it again every few seconds."] = "No se puede acceder al servidor de OmniVoice. Las respuestas se muestran como texto hasta que responda. El mod vuelve a preguntarle cada pocos segundos.",
    ["The clipboard does not hold a server address."] = "El portapapeles no contiene ninguna dirección de servidor.",
    ["The clipboard is empty. Copy the address first."] = "El portapapeles está vacío. Copie primero la dirección.",
    ["The port must be a number from 1 to 65535."] = "El puerto debe ser un número del 1 al 65535.",
    ["The server address was removed."] = "La dirección del servidor se ha eliminado.",
    ["The server answered but could not load its voice. Its window says why."] = "El servidor respondió, pero no pudo cargar su voz. Su ventana indica el motivo.",
    ["The server answered but is still loading its voice. Try again in a minute."] = "El servidor respondió, pero todavía está cargando su voz. Inténtelo de nuevo dentro de un minuto.",
    ["The server is another version. Use the server folder and the mod from the same release."] = "El servidor es otra versión. Use la carpeta del servidor y el mod de la misma versión.",
    ["The server is ready."] = "El servidor está listo.",
    ["The server refused the request."] = "El servidor rechazó la solicitud.",
    ["The server took too long to answer."] = "El servidor tardó demasiado en responder.",
    ["Use the address only: no user name, no path, no #."] = "Introduzca solo la dirección: sin nombre de usuario, sin ruta y sin #.",
    ["Use the address the server window shows, such as 192.168.1.20:8765, without https://."] = "Introduzca la dirección que muestra la ventana del servidor, como 192.168.1.20:8765, sin https://.",
    ["Waiting for the server to answer…"] = "Esperando a que el servidor responda…",
    ["Whether the server is in use right now. It is checked when a voice is needed and again every few seconds after a failure, never while you play."] = "Indica si el servidor está en uso en este momento. Se comprueba cuando se necesita una voz y de nuevo cada pocos segundos tras un fallo, nunca mientras juega.",
    ["Your own character, made in the character editor."] = "Tu propio personaje, creado en el editor de personajes.",
    ["Build for your game"] = "Compilación para tu juego",
    ["Your game is {game} but the Runtime is the one for game {runtime}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over this one, then restart the game."] = "Tu juego es {game}, pero el Runtime es el del juego {runtime}. Descarga el zip de instalación completo para el juego {game} desde la página del mod en Nexus Mods (archivo principal para el juego 2.5, archivo opcional para el juego 2.31), extráelo en la carpeta de Cyberpunk 2077 sobre la actual y luego reinicia el juego.",
    ["Your game is {game} but the Scripts are the build for game {scripts}. Get the update zip for game {game} from the mod’s Nexus Mods page (the update file is for game 2.5, the optional update file for game 2.31) and install it over these, then restart the game."] = "Tu juego es {game}, pero los Scripts son la build para el juego {scripts}. Descarga el zip de actualización para el juego {game} desde la página del mod en Nexus Mods (la actualización es para el juego 2.5, la actualización opcional para el juego 2.31), instálalo sobre los actuales y luego reinicia el juego.",
    ["Your game is {game} but the Scripts and the Runtime are the build for game {scripts}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over these, then restart the game."] = "Tu juego es {game}, pero los Scripts y el Runtime son la build para el juego {scripts}. Descarga el zip de instalación completo para el juego {game} desde la página del mod en Nexus Mods (archivo principal para el juego 2.5, archivo opcional para el juego 2.31), extráelo en la carpeta de Cyberpunk 2077 sobre los actuales y luego reinicia el juego.",
    ["The Scripts are the build for game {scripts} but the Runtime is the build for game {runtime}, and the game version matches neither. Extract the full install zip made for the same game as yours (from Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Los Scripts son la build para el juego {scripts}, pero el Runtime es la build para el juego {runtime}, y la versión del juego no coincide con ninguno. Extrae el zip de instalación completo hecho para el mismo juego que el tuyo (desde Nexus Mods) en la carpeta de Cyberpunk 2077 y luego reinicia el juego.",
    ["The Runtime is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Runtime del juego {other}, el tuyo es {game}. Consigue el zip completo para {game}.",
    ["The Scripts are for game {other}, yours is {game}. Get the update zip for {game}."] = "Scripts para {other}, el tuyo es {game}. Consigue el zip de update para {game}.",
    ["This mod is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Este mod es para el juego {other}, el tuyo es {game}. Consigue el zip completo para {game}.",
    ["Scripts are for game {scripts}, Runtime for {runtime}. They must match. See Help in Settings."] = "Scripts para {scripts}, Runtime para {runtime}. Deben coincidir: ver Ayuda en Ajustes.",
    ["Choose one of the listed microphones."] = "Elige uno de los micrófonos de la lista.",
    ["Microphone"] = "Micrófono",
    ["The microphone you chose in Settings ({chosen}) is not connected, so the Windows default input is used: {name}."] = "El micrófono que elegiste en Ajustes ({chosen}) no está conectado, así que se usa la entrada predeterminada de Windows: {name}.",
    ["The microphone you chose in Settings is not connected, so the Windows default input is used."] = "El micrófono que elegiste en Ajustes no está conectado, así que se usa la entrada predeterminada de Windows.",
    ["Windows default"] = "Predeterminado de Windows",
    ["not connected"] = "no conectado",
    ["{name}, chosen in Settings > Voices."] = "{name}, elegido en Ajustes > Voces.",
    ["{name}, the Windows default input. Settings > Voices > Microphone chooses another."] = "{name}, la entrada predeterminada de Windows. Otra se elige en Ajustes > Voces > Micrófono.",
    ["Revenge ambushes"] = "Emboscadas de venganza",
    ["Speak dialogue choices"] = "Decir las opciones de diálogo",
    ["Say a dialogue choice to pick it: its words, a part of them, or its number (\"two\", \"the last one\"). If nothing fits clearly, nothing is picked. No character answers.\n\nPresses the arrow keys and Enter, so the game must be in front. Needs speech recognition on this PC. Headphones work best."] = "Di una opción de diálogo para elegirla: sus palabras, una parte de ellas o su número (\"dos\", \"la última\"). Si nada encaja claramente, no se elige nada. Ningún personaje responde.\n\nPulsa las teclas de flecha y Enter, así que el juego debe estar en primer plano. Necesita reconocimiento de voz en este PC. Los auriculares funcionan mejor.",
    ["No option matched. Say its number."] = "Ninguna opción coincide. Di su número.",
    ["Two options fit. Say its number."] = "Dos opciones encajan. Di su número.",
    ["Speaking a choice needs speech recognition on this PC."] = "Decir una opción necesita reconocimiento de voz en este PC.",
    ["AMD’s ROCm PyTorch does not support this card yet."] = "El ROCm PyTorch de AMD todavía no admite esta tarjeta.",
    ["Another setup is already running. Wait for it to finish."] = "Otra configuración ya se está ejecutando. Espera a que termine.",
    ["Cancelled"] = "Cancelado",
    ["Cancelling…"] = "Cancelando…",
    ["Checking your card…"] = "Comprobando tu tarjeta…",
    ["Downloading {done} of {total} MB ({percent}%)"] = "Descargando {done} de {total} MB ({percent}%)",
    ["Downloading…"] = "Descargando…",
    ["Experimental. Pocket speaks until it is ready. A local voice never switches to a cloud voice."] = "Experimental. Pocket habla hasta que esté listo. Una voz local nunca cambia a una voz en la nube.",
    ["Frees about {disk} GB."] = "Libera unos {disk} GB.",
    ["Frees the space it took."] = "Libera el espacio que ocupó.",
    ["Install"] = "Instalar",
    ["Installed"] = "Instalado",
    ["Installed. OmniVoice uses it when it starts."] = "Instalado. OmniVoice lo usa cuando se inicia.",
    ["It is kept in the mod’s data folder on drive C:."] = "Se guarda en la carpeta de datos del mod, en la unidad C:.",
    ["It runs in the background while you play. The game keeps running and nothing else changes."] = "Se ejecuta en segundo plano mientras juegas. El juego sigue funcionando y no cambia nada más.",
    ["It takes about {disk} GB on drive C: in the mod’s data folder."] = "Ocupa unos {disk} GB en la unidad C:, en la carpeta de datos del mod.",
    ["MIOpen convolutions (AMD)"] = "Convoluciones de MIOpen (AMD)",
    ["Not available on this PC. It needs an AMD Radeon card and the OmniVoice pack."] = "No disponible en este PC. Necesita una tarjeta AMD Radeon y el paquete de OmniVoice.",
    ["OmniVoice for AMD"] = "OmniVoice para AMD",
    ["OmniVoice on AMD: set up first"] = "OmniVoice en AMD: configúralo primero",
    ["OmniVoice then no longer starts on this card until it is set up again."] = "Entonces OmniVoice ya no se inicia con esta tarjeta hasta que lo configures de nuevo.",
    ["On: AMD’s MIOpen runs the convolutions, with MIOPEN_FIND_MODE=2 and MIOPEN_FIND_ENFORCE=1. Off: PyTorch’s own convolutions. Which is faster depends on your card and driver: if voices are slow or stop part-way, try the other one. AMD cards only. OmniVoice restarts with the new choice when it is idle."] = "Activado: MIOpen de AMD ejecuta las convoluciones, con MIOPEN_FIND_MODE=2 y MIOPEN_FIND_ENFORCE=1. Desactivado: las convoluciones propias de PyTorch. Cuál es más rápida depende de tu tarjeta y de tu controlador: si las voces van lentas o se cortan a mitad, prueba la otra. Solo tarjetas AMD. OmniVoice se reinicia con la nueva opción cuando está inactivo.",
    ["Own Python"] = "Python propio",
    ["Ready"] = "Listo",
    ["Ready. OmniVoice runs on {card} with AMD’s ROCm."] = "Listo. OmniVoice se ejecuta en {card} con ROCm de AMD.",
    ["Reinstall"] = "Reinstalar",
    ["Remove AMD setup"] = "Quitar la configuración de AMD",
    ["Removing the AMD setup…"] = "Quitando la configuración de AMD…",
    ["Run OmniVoice on your AMD Radeon card with AMD’s ROCm: one download, set up from here."] = "Ejecuta OmniVoice en tu tarjeta AMD Radeon con ROCm de AMD: una sola descarga, configurada desde aquí.",
    ["Set up OmniVoice for AMD"] = "Configurar OmniVoice para AMD",
    ["Starting the AMD setup…"] = "Iniciando la configuración de AMD…",
    ["Testing it on your card…"] = "Probándolo en tu tarjeta…",
    ["The AMD setup was removed."] = "Se quitó la configuración de AMD.",
    ["The OmniVoice pack is not installed. Install it first."] = "El paquete de OmniVoice no está instalado. Instálalo primero.",
    ["The conversation service is not running. Restart the game."] = "El servicio de conversación no está en marcha. Reinicia el juego.",
    ["The download did not finish. Check your connection and try again."] = "La descarga no terminó. Revisa tu conexión e inténtalo de nuevo.",
    ["The download is not ready yet in this version of the mod."] = "La descarga todavía no está lista en esta versión del mod.",
    ["The downloaded files did not check out. Try again."] = "Los archivos descargados no pasaron la comprobación. Inténtalo de nuevo.",
    ["The files could not be unpacked. Try again."] = "No se pudieron descomprimir los archivos. Inténtalo de nuevo.",
    ["The setup did not finish. Try again."] = "La configuración no terminó. Inténtalo de nuevo.",
    ["The setup did not pass the test on your card, so OmniVoice cannot use it."] = "La configuración no superó la prueba en tu tarjeta, así que OmniVoice no puede usarla.",
    ["The setup is installed but did not pass the test on your card. Choose Reinstall."] = "La configuración está instalada, pero no superó la prueba en tu tarjeta. Elige Reinstalar.",
    ["There is not enough free space on drive C:. Free some up and try again."] = "No hay suficiente espacio libre en la unidad C:. Libera un poco e inténtalo de nuevo.",
    ["This PC has no AMD Radeon card this setup can use."] = "Este PC no tiene una tarjeta AMD Radeon que esta configuración pueda usar.",
    ["Unpacking…"] = "Descomprimiendo…",
    ["Your own Python (omni-python.txt) is used instead. Delete that file to use this setup."] = "Se usa tu propio Python (omni-python.txt) en su lugar. Borra ese archivo para usar esta configuración.",
    ["your AMD card"] = "tu tarjeta AMD",
    ["{voice} · AMD: set up first"] = "{voice} · AMD: configúralo primero",
    ["The AMD setup (Settings > Voices > OmniVoice for AMD) runs OmniVoice with ROCm on {card}. Experimental."] = "La configuración para AMD (Ajustes > Voces > OmniVoice para AMD) ejecuta OmniVoice con ROCm en {card}. Experimental.",
    ["The AMD setup was not used: {reason}. Choose Reinstall in Settings > Voices > OmniVoice for AMD. Until then Pocket speaks."] = "La configuración para AMD no se usó: {reason}. Elige Reinstalar en Ajustes > Voces > OmniVoice para AMD. Mientras tanto habla Pocket.",
    ["Borrow eddies from your characters, lend them eddies and pay each other back, by talking. Each character has money of their own, as their story has it, and decides by how they feel about you. Now and then they ask you for a loan.\n\nEddies change hands as soon as a character agrees, and only with your own characters (party, invited visitors, housemates). The game’s own characters only talk about it. Off by default."] = "Pide eddies prestados a tus personajes y préstales eddies hablando. Cada uno tiene su propio dinero según su historia y decide según lo que siente por ti. De vez en cuando te piden un préstamo.\n\nLos eddies cambian de manos en cuanto un personaje acepta, y solo con tus propios personajes (grupo, visitantes, compañeros de piso). Los del juego solo hablan de ello. Desactivado por defecto.",
    ["Eddies with characters"] = "Eddies con personajes",
    ["The eddies could not be moved."] = "No se pudieron mover los eddies.",
    ["You do not have enough eddies for that."] = "No tienes suficientes eddies para eso.",
    ["{name} is no longer with you, so no eddies moved."] = "{name} ya no está contigo, así que no se movieron eddies.",
    ["Add to favorites"] = "Añadir a favoritos",
    ["One download of about {size} GB."] = "Una descarga de unos {size} GB.",
    ["One download."] = "Una descarga.",
    ["Remove from favorites"] = "Quitar de favoritos",
    ["Set up OmniVoice on your AMD Radeon card with one download, and choose how it runs."] = "Configura OmniVoice en tu tarjeta AMD Radeon con una sola descarga y elige cómo se ejecuta.",
    ["That entry cannot be a favorite."] = "Esa entrada no puede ser un favorito.",
    ["You have too many favorites. Remove one first."] = "Tienes demasiados favoritos. Quita primero uno.",
    ["Your AMD Radeon card ({card}) can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself."] = "Tu tarjeta AMD Radeon ({card}) puede ejecutar OmniVoice. Configúralo en Ajustes > Voces > OmniVoice para AMD: una descarga y luego arranca solo.",
    ["Your favorites could not be saved, so they last only until the game closes."] = "No se pudieron guardar tus favoritos, así que solo duran hasta que se cierre el juego.",
    ["{count} matching characters"] = "{count} personajes coincidentes",
    ["{name} is no longer a favorite."] = "{name} ya no es un favorito.",
    ["A saved party holds {count} characters, so the rest were left out."] = "Un grupo guardado admite {count} personajes, así que el resto se dejó fuera.",
    ["Already with you: {names}."] = "Ya están contigo: {names}.",
    ["Another saved party already has that name."] = "Otro grupo guardado ya tiene ese nombre.",
    ["Could not invite: {names}."] = "No se pudo invitar: {names}.",
    ["Deletes this saved party. The characters in your party now are not touched."] = "Elimina este grupo guardado. Los personajes de tu grupo actual no se tocan.",
    ["Invites the characters of this party to your side: {names}.\n\nIt adds to your party and dismisses nobody. A character who is already with you is not invited twice. Anyone who cannot come is named, with the reason."] = "Invita a los personajes de este grupo a tu lado: {names}.\n\nSe añaden a tu grupo y no se despide a nadie. Un personaje que ya está contigo no se invita dos veces. Quien no pueda venir se indica junto con el motivo.",
    ["Parties"] = "Grupos",
    ["Party"] = "Grupo",
    ["Press Delete again to delete {name}."] = "Pulsa Eliminar de nuevo para eliminar a {name}.",
    ["Press again"] = "Pulsa de nuevo",
    ["Press again to delete this saved party. Anything else cancels."] = "Pulsa de nuevo para eliminar este grupo guardado. Cualquier otra cosa cancela.",
    ["Rename"] = "Renombrar",
    ["Rename party"] = "Renombrar grupo",
    ["Renamed to {name}."] = "Renombrado como {name}.",
    ["Replaces the characters of this saved party with the ones in your party now."] = "Reemplaza los personajes de este grupo guardado por los de tu grupo actual.",
    ["Save current party"] = "Guardar grupo actual",
    ["Saved as {name}. Press Spawn party under it to invite them again."] = "Guardado como {name}. Pulsa Invitar grupo debajo para invitarlos de nuevo.",
    ["Saved party: {name}"] = "Grupo guardado: {name}",
    ["Saves the characters in your party now, copies and your own characters included, as a party you can invite again with one press. It is named Party 1, Party 2 and so on, and appears below.\n\nYou keep up to {count} saved parties."] = "Guarda los personajes que tienes ahora en tu grupo, incluidas las copias y tus propios personajes, como un grupo que puedes volver a invitar con una sola pulsación. Se llamará Grupo 1, Grupo 2 y así sucesivamente, y aparecerá abajo.\n\nPuedes conservar hasta {count} grupos guardados.",
    ["Spawn"] = "Invitar",
    ["Spawn party"] = "Invitar grupo",
    ["That party no longer exists."] = "Ese grupo ya no existe.",
    ["The characters of this party: {names}."] = "Los personajes de este grupo: {names}.",
    ["The party could not be saved."] = "No se pudo guardar el grupo.",
    ["This menu has no text box, so the party keeps its name. Mod Configuration Menu has one: type the name in its Search box."] = "Este menú no tiene campo de texto, así que el grupo conserva su nombre. Mod Configuration Menu sí tiene: escribe el nombre en su campo de búsqueda.",
    ["Type the new name in the Search box at the top (Mod Configuration Menu), then press Rename. Native Settings UI has no text box, so a party keeps its name there."] = "Escribe el nuevo nombre en el campo de búsqueda de arriba (Mod Configuration Menu) y luego pulsa Renombrar. Native Settings UI no tiene campo de texto, así que allí un grupo conserva su nombre.",
    ["Type the new name in the Search box first, then press Rename."] = "Escribe primero el nuevo nombre en el campo de búsqueda y luego pulsa Renombrar.",
    ["Update"] = "Actualizar",
    ["Update with current party"] = "Actualizar con grupo actual",
    ["You can keep {count} saved parties. Delete one first."] = "Puedes conservar {count} grupos guardados. Elimina uno primero.",
    ["Your party is empty. Invite someone first."] = "Tu grupo está vacío. Invita a alguien primero.",
    ["Your saved parties could not be written to disk, so they last only until the game closes."] = "Tus grupos guardados no se pudieron escribir en el disco, así que solo durarán hasta que se cierre el juego.",
    ["that character model is unavailable"] = "el modelo de personaje no está disponible",
    ["the invitation was refused"] = "la invitación fue rechazada",
    ["{name} ({count})"] = "{name} ({count})",
    ["{name} ({reason})"] = "{name} ({reason})",
