    ["{name} has nobody to invite."] = "{name} no tiene a nadie a quien invitar.",
    ["{name} now has the characters of your party."] = "{name} ahora tiene los personajes de tu grupo.",
    ["{party}: inviting {names}."] = "{party}: invitando a {names}.",
    ["Adds {name} to your favorites. They are listed at the top of page 1, and first in the phone’s Chat tab. Updates never touch them."] = "Añade {name} a favoritos. Aparecen al principio de la página 1 y primero en la pestaña Chat del teléfono. Las actualizaciones nunca los tocan.",
    ["Favorites"] = "Favoritos",
    ["Only the first {count} favorites are listed here. The others are in the list below."] = "Aquí solo aparecen los primeros {count} favoritos. Los demás están en la lista de abajo.",
    ["Page {page} of {pages}: {kind} {first} to {last}."] = "Página {page} de {pages}: {kind} {first} a {last}.",
    ["Press to go to page {page} of {pages}: {kind} {first} to {last}."] = "Pulsa para ir a la página {page} de {pages}: {kind} {first} a {last}.",
    ["Takes {name} out of your favorites. Her place in the list below stays."] = "Quita a {name} de favoritos. Su lugar en la lista de abajo se mantiene.",
    ["This is the first page."] = "Esta es la primera página.",
